  (* LPS 727298f3 port: the channel reader along the free-to-exit path.  The path's models
     are related by [same_but_materialized], then [as_MPRES], then [same_but_materialized],
     and each keeps [m_channel_reader] ([same_but_materialized_reader], [adl_rdr]). *)
  Lemma ftx_reader : forall mo mo1 mo2 mo3,
    OSSVerify.Proofs.boost_json.fuzz_parse.lib.LazyRestrict.same_but_materialized mo mo1 -> as_MPRES H mo1 mo2 -> OSSVerify.Proofs.boost_json.fuzz_parse.lib.LazyRestrict.same_but_materialized mo2 mo3 ->
    m_channel_reader mo3 = m_channel_reader mo.
  Proof.
    intros mo mo1 mo2 mo3 S1 M2 S3.
    rewrite (OSSVerify.Proofs.boost_json.fuzz_parse.lib.LazyRestrict.same_but_materialized_reader _ _ S3).
    assert (E2 : m_channel_reader mo2 = m_channel_reader mo1) by (eapply adl_rdr; eassumption).
    rewrite E2. exact (OSSVerify.Proofs.boost_json.fuzz_parse.lib.LazyRestrict.same_but_materialized_reader _ _ S1).
  Qed.

  Lemma ftx_reader_true : forall mo mo3,
    m_channel_reader mo3 = m_channel_reader mo -> m_channel_reader mo = true -> m_channel_reader mo3 = true.
  Proof. intros mo mo3 E R. rewrite E. exact R. Qed.

  (* LPS 727298f3 port: [free_to_exit] whose continuation also receives the reader equality,
     conjoined to the fd equality ([ftx_reader]); the recorded proof of [free_to_exit] with
     that one premise and its one argument changed, for [free_exit2], whose write needs the
     reader at the exit. *)
  Lemma free_to_exit_r : forall axc s msF mo regs mem p (A cap : Z) (status : word) (pending : list byte) junk (K : TSet),
    ax_shape axc ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xbeab0) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    getr regs 2 = Z_to_bv 64 (bv_unsigned sp0 - 128) -> getr regs 4 = Z_to_bv 64 ATP -> getr regs 8 = status -> getr regs 9 = Z_to_bv 64 A ->
    bv_unsigned status < 256 ->
    as_RHEAP H s [(p, A, cap)] mem -> rw_cells asegs mem A [CB (Z.to_nat cap) junk] -> addressable mem A cap ->
    as_Cf H cap <= as_AL H s ->
    xstat axc mem -> ostate pending mem ->
    (forall regs3 mem2 msF3 mo3 Lz Sz Zr,
        xstat axc mem2 -> ostate pending mem2 ->
        getr regs3 2 = Z_to_bv 64 (bv_unsigned sp0 - 48) -> getr regs3 4 = Z_to_bv 64 ATP -> getr regs3 10 = status ->
        m_fs mo3 = m_fs mo -> m_fds mo3 = m_fds mo /\ m_channel_reader mo3 = m_channel_reader mo ->
        lzok RSEGS Lz Sz Zr (mkCfg msF3 mo3) -> restrict Lz Sz msF3 = mkst regs3 (Z_to_bv 64 AEXIT) mem2 (seg_rom RSEGS) ->
        realizes asegs (mkCfg msF3 mo3) K) ->
    realizes asegs (mkCfg msF mo) K.
Proof.
