  Theorem refuse_exit : forall mem0 pp fs0 s msF mo regs mem p (A : Z),
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xbeb04) mem rom -> as_AKREL H s (mkCfg msF mo) ->
